import{z as s,x as m,o as t,c as p,q as i,j as o,D as a,d as l,s as d,S as E,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"双端优先队列","description":"","frontmatter":{"title":"双端优先队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/double-ended-pq.md","filePath":"cs/double-ended-pq.md","lastUpdated":1791063341000}'),B={name:"cs/double-ended-pq.md"};function A(h,e,c,u,x,D){const r=m("Mermaid");return t(),p("div",null,[e[2]||(e[2]=i('<h1 id="双端优先队列" tabindex="-1">双端优先队列 <a class="header-anchor" href="#双端优先队列" aria-label="Permalink to &quot;双端优先队列&quot;">​</a></h1><div class="epigraph"><p>既要 $O(\\log n)$ 抽最小，也要 $O(\\log n)$ 抽最大；一个堆序不够，除非成对放置或两堆互指。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 3；Sedgewick and Wayne；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/mergeable-heap">上一课</a>的堆合同围绕同一端极值。<a href="/cs/deque">双端队列</a> 两端是位置不是键序。本课不 meld。缺口是双端优先队列（DEPQ）：<code>insert</code>、<code>get-min</code>/<code>delete-min</code>、<code>get-max</code>/<code>delete-max</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个独立堆（一个 min 一个 max）各插一份，删除时要同步删另一边，需要句柄或懒删。间隔堆（interval heap）：完全树每个节点存一对 \\((a,b)\\)，\\(a\\le b\\)，左端形成 min-heap 序、右端 max-heap 序。或 min-max 堆：偶数层 min、奇数层 max。缺口是<strong>在一份存储里同时维持两种堆序</strong>，避免 \\(2n\\) 全量复制。</p><p><span class="marginnote">Knuth 卷 3 讨论优先队列变体。教材中 interval heap 与 min-max heap 是常见两种表示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>insert：放入末叶再沿 min 或 max 路径上滤，视新键与所在对/层的关系。delete-min：与普通堆类似，空洞从根补，但要同时修复另一端序。实现细节因表示而异，合同统一为两端对数。</p>',8)),(t(),o(E,null,{default:a(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22insert%22%5D%20--%3E%20DEPQ%5B%22%E5%8F%8C%E7%AB%AF%E4%BC%98%E5%85%88%E9%98%9F%E5%88%97%22%5D%0A%20%20DEPQ%20--%3E%20MIN%5B%22delete-min%22%5D%0A%20%20DEPQ%20--%3E%20MAX%5B%22delete-max%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n("p",null,"与有序 BST：顺序统计树也能删最小最大（最左最右），还能 rank；DEPQ 不支持任意键查找，常数按堆。选结构看操作集。",-1)),e[4]||(e[4]=n("h2",{id:"机制",tabindex:"-1"},[l("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=n("p",null,"不能只用一个 min-heap 另存当前 max 变量：删 max 后 max 未知，除非扫。成对或分层把「另一端候选」永远放在堆路径上。空间 \\(\\Theta(n)\\)。",-1)),(t(),o(E,null,{default:a(()=>[d(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%E8%8A%82%E7%82%B9%E5%AF%B9%20(1%2C%2099)%EF%BC%9A%E5%90%AB%E5%85%A8%E5%B1%80%E6%9C%80%E5%B0%8F%E4%B8%8E%E6%9C%80%E5%A4%A7%22%5D%20--%3E%20L%5B%22%E5%B7%A6%E5%AD%90%E8%8A%82%E7%82%B9%E5%AF%B9%20(2%2C%209)%22%5D%0A%20%20R%20--%3E%20RR%5B%22%E5%8F%B3%E5%AD%90%E8%8A%82%E7%82%B9%E5%AF%B9%20(10%2C%2080)%22%5D%0A%20%20L%20--%3E%20LL%5B%22%E5%AD%99%E8%8A%82%E7%82%B9%E5%AF%B9%20(3%2C%207)%22%5D%0A%20%20L%20--%3E%20LR%5B%22%E5%AD%99%E8%8A%82%E7%82%B9%E5%AF%B9%20(4%2C%206)%22%5D%0A%20%20R%20--%3E%7C%22%E6%B2%BF%E5%B7%A6%E7%AB%AF%E8%AF%BB%EF%BC%9A1%20%E2%89%A4%202%20%E2%89%A4%203%EF%BC%8Cmin-heap%20%E5%BA%8F%22%7C%20MIN%5B%22get-min%20%E5%B8%B8%E6%95%B0%E6%97%B6%E9%97%B4%22%5D%0A%20%20R%20--%3E%7C%22%E6%B2%BF%E5%8F%B3%E7%AB%AF%E8%AF%BB%EF%BC%9A99%20%E2%89%A5%2080%20%E2%89%A5%206%EF%BC%8Cmax-heap%20%E5%BA%8F%22%7C%20MAX%5B%22get-max%20%E5%B8%B8%E6%95%B0%E6%97%B6%E9%97%B4%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">数字实例：为什么不能「min-heap 加一个 max 变量」凑合——\\(n=100\\) 万时，删掉 max 之后想找新的最大值，只能线性扫描约 100 万个元素，\\(O(n)\\)；而 interval heap 上做 delete-max 只要沿一条路径下滤，约 \\(\\log_2 n \\approx 20\\) 步。</span></p><p><span class="marginnote">直觉类比：interval heap 像每个房间住两个人——矮个子住左边、高个子住右边。所有房间的「矮个子」按越往下越矮排好，所有「高个子」按越往下越矮也排好；于是全局最矮和最高的人都住在同一个房间（根节点）里。</span></p><p><span class="marginnote">常见误区：初学者容易把 DEPQ 和 <a href="/cs/deque">deque</a> 混为一谈。deque 的「两端」是插入位置（队头进、队尾出），跟键值大小无关；DEPQ 的「两端」是键的最小值和最大值，跟你从哪头插入无关。名字像，合同完全不同。</span></p><p>不要与 deque 的「两端下标」混淆：DEPQ 的两端是键的极值。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把无锁 DEPQ 写完。整数键、宇宙 \\([0,U)\\) 上找后继，堆帮不上忙——那是 van Emde Boas 的 \\(O(\\log\\log U)\\)，下一课换模型。</p><p>后课默认：两端极值用 DEPQ 或有序树。有界整数宇宙上的前驱后继，用 vEB。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DEPQ：min 与 max 都对数，不是位置 deque。</li><li>表示：interval heap、min-max 堆、或双堆加句柄。</li><li>整数宇宙前驱后继交给 vEB。</li><li>出处：Knuth 卷 3；Sedgewick and Wayne；Cormen et al.。</li></ul>',9))])}const g=s(B,[["render",A]]);export{f as __pageData,g as default};
